                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.gs_wh_union AS SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh1_oct where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh1_nov where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh1_dec where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh2_oct where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh2_nov where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs__wh2_dec where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs_emiza_rto where awb_number is not null UNION ALL SELECT name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date FROM snitch_db.maplemonk.gs_emiza_dto where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_jan_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_jan_wh2 where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_feb_wh2 where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_feb_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_mar_wh2 where awb_number is not null UNION ALL select name, count,packet,channel,\"rto/dto\",warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_mar_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_apr_wh2 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_apr_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_may_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_may_wh2 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_jun_wh1 where awb_number is not null UNION ALL select name, count,packet,channel,rto_dto,warehouse, logistics,qc_status,awb_number,scanning_done,receiving_date,processing_date from snitch_db.maplemonk.gs_jun_wh2 where awb_number is not null ; create or replace table snitch_db.maplemonk.gs_wh_returns1 as WITH ReturnsCTE as ( SELECT CASE WHEN lower(receiving_date) like \'%back%\' then \'2025-01-01\' ELSE TO_DATE(receiving_date, \'DD/MM/YYYY\') END AS receiving_date1, TO_DATE(processing_date, \'DD/MM/YYYY\') AS processing_date, UPPER(CAST(awb_number AS TEXT)) AS awb_number, CAST(scanning_done AS TEXT) AS scanning_done, CAST(name AS TEXT) AS name, CAST(warehouse AS TEXT) AS warehouse, CASE WHEN lower(CHANNEL) like \'%ajio%\' then \'AJIO\' WHEN lower(CHANNEL) like \'%myntra%\' then \'MYNTRA\' WHEN lower(CHANNEL) like \'%shopify\' then \'SHOPIFY\' WHEN lower(CHANNEL) like \'%flipkart%\' then \'FLIPKART\' WHEN lower(CHANNEL) like \'%amazon%\' then \'AMAZON\' ELSE \'SHOPIFY\' END AS channel , CAST(\"rto/dto\" AS TEXT) AS rto_dto, CAST(logistics AS TEXT) AS logistics, CAST(qc_status AS TEXT) AS qc_status, count, CAST(packet AS TEXT) AS packet, DATEDIFF(DAY, receiving_date1, TO_DATE(processing_date, \'DD/MM/YYYY\')) AS processing_days FROM snitch_db.maplemonk.gs_wh_union WHERE awb_number IS NOT NULL ), LatestReversePickup AS ( SELECT rp.\"Tracking No\", rp.\"Channel Name\", rp.\"Sale Order Item Code\", rp.\"Original Sale Order Code\", rp.\"Reverse Pickup Status\", rp.\"Return Delivery Date\", rp.\"Putaway Last Updated\", rp.\"Reverse Pickup Last Updated\" AS processed_date, ROW_NUMBER() OVER (PARTITION BY rp.\"Tracking No\" ORDER BY rp.\"Reverse Pickup Last Updated\" DESC) AS row_num FROM snitch_db.maplemonk.snitch_get_copy_of_reverse_pickup rp ), FilteredReversePickup AS ( SELECT \"Tracking No\", \"Channel Name\", \"Sale Order Item Code\", \"Original Sale Order Code\", \"Reverse Pickup Status\", \"Return Delivery Date\", \"Putaway Last Updated\", processed_date FROM LatestReversePickup WHERE row_num = 1 ) SELECT r.receiving_date1 as receiving_date, r.processing_date, r.awb_number, r.scanning_done, r.name, r.warehouse, r.channel, r.rto_dto, r.logistics, r.qc_status, r.count, r.packet, r.processing_days, case when rp.\"Putaway Last Updated\" < rp.processed_date THEN rp.\"Putaway Last Updated\" else rp.processed_date end as revised_processed_date, CASE WHEN r.rto_dto = \'DTO\' THEN rp.\"Tracking No\" ELSE cr.\"AWB No\" END AS tracking_number, COALESCE(rp.\"Reverse Pickup Status\", cr.\"Return Status\") AS return_status, TO_TIMESTAMP( COALESCE( NULLIF(revised_processed_date, \'\'), NULLIF(cr.\"Return Date\", \'\'), NULL ) ) AS \"Processed Date\", TO_TIMESTAMP( COALESCE( NULLIF(rp.\"Return Delivery Date\", \'\'), NULLIF(cr.\"Return Delivery Date\", \'\'), receiving_date ) ) AS RDD, DATEDIFF( DAY, CAST( COALESCE( NULLIF(rp.\"Return Delivery Date\", \'\'), NULLIF(cr.\"Return Delivery Date\", \'\'), receiving_date ) AS DATE ), CAST( COALESCE( NULLIF(revised_processed_date, \'\'), NULLIF(cr.\"Return Date\", \'\'), r.processing_date ) AS DATE ) ) AS UCprocessing_days, coalesce(rp.\"Channel Name\",cr.\"Channel Name\") as Marketplace, coalesce(rp.\"Sale Order Item Code\",cr.\"Sale Order Item\") as SaleOrderItemCode, coalesce(rp.\"Original Sale Order Code\",cr.\"Sale Order No\") as order_id, CASE WHEN DATEDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) < 2 THEN \'<2D\' WHEN TIMESTAMPDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 2 AND 5 THEN \'<5D\' WHEN TIMESTAMPDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) between 5 and 10 THEN \'<10D\' WHEN TIMESTAMPDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 10 AND 15 THEN \'<15D\' WHEN TIMESTAMPDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 15 AND 30 THEN \'<30D\' WHEN TIMESTAMPDIFF(DAY, receiving_date, CONVERT_TIMEZONE(\'Canada/Pacific\', \'Asia/Kolkata\', CURRENT_TIMESTAMP)) BETWEEN 30 AND 60 THEN \'<60D\' ELSE \'>60D\' END as pendency_ageing, DATEDIFF(DAY, receiving_date,processing_date) as processing_time FROM ReturnsCTE r LEFT JOIN FilteredReversePickup rp ON r.awb_number = rp.\"Tracking No\" LEFT JOIN snitch_db.maplemonk.snitch_db_get_courier_returns_itemwise_new cr ON r.awb_number = cr.\"AWB No\"; create or replace table snitch_db.maplemonk.gs_wh_returns as with returns as ( select * from snitch_db.maplemonk.gs_wh_returns1 ), errors as ( select awb_number as awb, raised_date,received_date,warehouse_name,error_type,reason,rto_dto,channel from snitch_db.maplemonk.gs_return_errors ), final AS ( SELECT r.*, e.raised_date, e.received_date, e.warehouse_name, e.error_type, e.reason, case when e.reason is not null then 1 END as error FROM returns r LEFT JOIN errors e ON r.awb_number = e.awb ) SELECT * FROM final;",
                    "transaction": true
                }
            ) }}
